/**
 * Entry point for the reusable "sync test plan" workflow (Requirement #35,
 * incremental regeneration follow-up). Runs on every push to a linked
 * project repo, alongside draft-log-entry — but does almost nothing on
 * most pushes: it only touches docs/TEST_PLAN.md when the project's own
 * docs/PRODUCT.md requirements have actually changed since the last
 * generation, detected per-requirement (not as one combined hash) via a
 * requirement-hashes marker embedded in the test plan's own banner.
 *
 * Three outcomes, cheapest first:
 *  - Nothing changed: true no-op, no Claude call, no commit.
 *  - Only already-in-scope requirement(s) changed or were newly added,
 *    AND at least one existing test case references one of them: a cheap
 *    patch — only the affected test case(s) are sent to Claude and
 *    spliced back in, leaving the rest of the file untouched.
 *  - Anything else (first-ever generation, a test plan predating this
 *    feature, a requirement removed, or a changed/added requirement with
 *    no existing test case to patch — e.g. one that only ever lived in
 *    the "Out of scope" list): a full regeneration, same as this action
 *    always did, just with a raised budget (see FULL_REGEN_MAX_TOKENS).
 *
 * Writes back into the project repo itself (source of truth), and
 * mirrors a copy into the vault at projects/<name>/test-plan.md — same
 * reason docs/PRODUCT.md gets mirrored (see productDoc.ts): the local
 * chat server's "Test plan" tab reads straight off disk, never the
 * GitHub API.
 */
export declare function syncTestPlan(): Promise<void>;
